"""Torus workflows, written once and rendered for each supported app.

Each workflow (review alerts, onboard companies, write a memo...) has one source
file under ``skills/``. It is rendered for three targets:

* ``code``    - Claude Code: the plugin's ``SKILL.md`` files (generated by
                ``scripts/build_plugin.py``; a test checks they match)
* ``desktop`` - Claude Desktop: MCP prompts served by ``torus serve``
* ``codex``   - Codex: skills that ``torus setup`` installs under
                ``$CODEX_HOME/skills``

Template syntax, kept small on purpose:

* ``<!-- if code -->`` / ``<!-- if desktop codex -->`` ... ``<!-- else -->`` ...
  ``<!-- end -->`` on lines of their own keep a block for some targets only
  (``apps`` means desktop and codex)
* ``{{review}}`` names another workflow the way the target invokes it
  (``/torus:review`` in Claude Code)
* ``{{include:company-mapper}}`` inserts the body of a Claude Code subagent
  (``agents/``), for targets that run its steps in the main conversation
* ``{{capture_mode}}`` is the capture mode the target uses
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from importlib import resources
from pathlib import Path
from typing import Literal

Target = Literal["code", "desktop", "codex"]
TARGETS: tuple[Target, ...] = ("code", "desktop", "codex")
APPS: frozenset[Target] = frozenset({"desktop", "codex"})
ALL: frozenset[Target] = frozenset(TARGETS)

CODEX_PREFIX = "torus-"


@dataclass(frozen=True)
class Argument:
    name: str
    description: str
    required: bool = False


@dataclass(frozen=True)
class Workflow:
    """One workflow: its source file, where it exists, and how apps present it."""

    name: str
    title: str
    targets: frozenset[Target] = ALL
    arguments: tuple[Argument, ...] = field(default=())
    prompt: str | None = None

    @property
    def codex_name(self) -> str:
        return CODEX_PREFIX + ("research" if self.name == "research-protocol" else self.name)

    @property
    def prompt_name(self) -> str:
        return self.prompt or self.name.replace("-", "_")


WORKFLOWS: tuple[Workflow, ...] = (
    # Desktop gets the research rules from the server instructions instead.
    Workflow("research-protocol", "Research with Torus", frozenset({"code", "codex"})),
    Workflow(
        "status",
        "Research status",
        arguments=(Argument("company", "A company or ticker to focus on (optional)"),),
    ),
    Workflow("review", "Review alerts", prompt="review_alerts"),
    Workflow(
        "onboard",
        "Onboard companies",
        arguments=(Argument("tickers", "Tickers or company names, e.g. NVDA AMD TSM"),),
    ),
    Workflow(
        "ingest",
        "Ingest a document",
        arguments=(Argument("url", "A filing (e.g. 'NVDA latest 10-K'), URL, or pasted text"),),
    ),
    Workflow(
        "whatif",
        "What if...?",
        arguments=(Argument("event", "A hypothetical event, e.g. 'TSMC fab outage'"),),
    ),
    Workflow(
        "challenge",
        "Challenge a thesis",
        arguments=(Argument("thesis", "The thesis to stress-test (a title, company or id)"),),
    ),
    Workflow("audit", "Audit the research"),
    Workflow("scorecard", "Thesis scorecard"),
    Workflow(
        "memo",
        "Write a thesis memo",
        arguments=(Argument("thesis", "The thesis to write up (a title, company or id)"),),
    ),
    Workflow("undo", "Undo recorded research"),
    Workflow(
        "explore",
        "Open the graph explorer",
        arguments=(Argument("focus", "Companies to centre on (optional)"),),
    ),
    # Claude Code distils transcripts with a curator; apps save the chat itself.
    Workflow("distill", "Distill sessions", frozenset({"code"})),
    Workflow("save-chat", "Save this chat to Torus", APPS, prompt="save_this_chat"),
)

BY_NAME = {w.name: w for w in WORKFLOWS}

_FRONTMATTER = re.compile(r"^---\n(.*?)\n---\n", re.DOTALL)
_IF = re.compile(r"^<!-- if ([a-z ]+) -->$")
_ELSE = "<!-- else -->"
_END = "<!-- end -->"
_REF = re.compile(r"\{\{([a-z_-]+)\}\}")
_INCLUDE = re.compile(r"^\{\{include:([a-z-]+)\}\}$", re.MULTILINE)


def _read(kind: str, name: str) -> str:
    return (resources.files(__package__) / kind / f"{name}.md").read_text("utf-8")


def _targets(spec: str) -> set[str]:
    words = set(spec.split())
    if "apps" in words:
        words = (words - {"apps"}) | set(APPS)
    unknown = words - set(TARGETS)
    if unknown:
        raise ValueError(f"unknown target(s) in template: {sorted(unknown)}")
    return words


def _conditionals(text: str, target: Target) -> str:
    out: list[str] = []
    keep: bool | None = None  # None: outside a block
    for line in text.split("\n"):
        if match := _IF.match(line):
            if keep is not None:
                raise ValueError("nested <!-- if --> blocks are not supported")
            keep = target in _targets(match.group(1))
        elif line == _ELSE:
            if keep is None:
                raise ValueError("<!-- else --> outside a block")
            keep = not keep
        elif line == _END:
            if keep is None:
                raise ValueError("<!-- end --> outside a block")
            keep = None
        elif keep is None or keep:
            out.append(line)
    if keep is not None:
        raise ValueError("unclosed <!-- if --> block")
    return "\n".join(out)


def target_for(harness: str) -> Target:
    """The render target for a ``TORUS_HARNESS`` value (unknown clients get prompts)."""
    value = harness.strip().lower()
    if value in ("claude-code", "test"):
        return "code"
    return "codex" if value == "codex" else "desktop"


def reference(name: str, target: Target) -> str:
    """How a user invokes workflow ``name`` in ``target``."""
    workflow = BY_NAME[name]
    if target == "code":
        return f"`/torus:{name}`"
    if target == "codex":
        return f"the `{workflow.codex_name}` skill"
    return f'the Torus "{workflow.title}" prompt'


def _refs(text: str, target: Target) -> str:
    def sub(match: re.Match[str]) -> str:
        key = match.group(1)
        if key == "capture_mode":
            return "${user_config.capture_mode}" if target == "code" else "live"
        if key in BY_NAME:
            return reference(key, target)
        raise ValueError(f"unknown reference {{{{{key}}}}}")

    return _REF.sub(sub, text)


def split_frontmatter(text: str) -> tuple[dict[str, str], str]:
    match = _FRONTMATTER.match(text)
    if not match:
        return {}, text
    fields = {}
    for line in match.group(1).splitlines():
        key, _, value = line.partition(":")
        fields[key.strip()] = value.strip()
    return fields, text[match.end() :]


def _render_text(text: str, target: Target) -> str:
    text = _conditionals(text, target)

    def include(match: re.Match[str]) -> str:
        _, agent_body = split_frontmatter(_read("agents", match.group(1)))
        return _render_text(agent_body, target).strip("\n")

    text = _INCLUDE.sub(include, text)
    return _refs(text, target)


def render(name: str, target: Target) -> str:
    """The whole skill file (frontmatter and body) for ``target``."""
    workflow = BY_NAME[name]
    if target not in workflow.targets:
        raise ValueError(f"workflow {name!r} is not available in {target}")
    text = _render_text(_read("skills", name), target)
    if target == "codex":
        fields, body = split_frontmatter(text)
        fields["name"] = workflow.codex_name
        head = "".join(f"{k}: {v}\n" for k, v in fields.items())
        text = f"---\n{head}---\n{body}"
    return text


def body(name: str, target: Target) -> str:
    """The instructions without frontmatter (what an MCP prompt sends)."""
    return split_frontmatter(render(name, target))[1].strip("\n") + "\n"


def description(name: str, target: Target) -> str:
    return split_frontmatter(render(name, target))[0].get("description", "")


def agent(name: str) -> str:
    """A Claude Code subagent file, as the plugin ships it."""
    return _read("agents", name)


def agent_names() -> list[str]:
    folder = resources.files(__package__) / "agents"
    return sorted(p.name.removesuffix(".md") for p in folder.iterdir() if p.name.endswith(".md"))


def for_target(target: Target) -> list[Workflow]:
    return [w for w in WORKFLOWS if target in w.targets]


def write_codex_skills(skills_dir: Path) -> list[Path]:
    """Install Torus skills for Codex under ``skills_dir`` (e.g. ``~/.codex/skills``)."""
    written: list[Path] = []
    for workflow in for_target("codex"):
        path = skills_dir / workflow.codex_name / "SKILL.md"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(render(workflow.name, "codex"), encoding="utf-8", newline="\n")
        written.append(path)
    return written


def write_claude_code_plugin(plugin_dir: Path) -> None:
    """Regenerate ``plugins/claude-code/skills`` and ``agents`` from the workflow sources."""
    for workflow in for_target("code"):
        path = plugin_dir / "skills" / workflow.name / "SKILL.md"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(render(workflow.name, "code"), encoding="utf-8", newline="\n")
    for name in agent_names():
        path = plugin_dir / "agents" / f"{name}.md"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(agent(name), encoding="utf-8", newline="\n")
